package net.civeira.phylax.feature.observe.alert;

import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import org.eclipse.microprofile.config.inject.ConfigProperty;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.notification.outbox.application.usecase.enqueue.EnqueueNotificationCommand;
import net.civeira.phylax.feature.notification.outbox.application.usecase.enqueue.EnqueueNotificationUseCase;
import net.civeira.phylax.feature.notification.outbox.domain.ChannelOptions;

/**
 * Channel {@code email} of the alerts (trait observable-notification): one message per recipient in
 * the outbox of multitenant-notification, rendered with the templates {@code observe.alert.firing}
 * / {@code observe.alert.resolved} that InstallObserveNotification seeds. The outbox brings the
 * retries and the SMTP configuration; a firing alert is sent as urgent. They are platform notices:
 * no tenant, the global SMTP configuration.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class NotificationAlertChannel implements AlertChannel {

  public static final String FIRING_TEMPLATE = "observe.alert.firing";
  public static final String RESOLVED_TEMPLATE = "observe.alert.resolved";

  private final EnqueueNotificationUseCase enqueue;
  private final @ConfigProperty(name = "app.observe.viewer.title",
      defaultValue = "phylax-api") String title;

  @Override
  public boolean accepts(final String channel) {
    return "email".equals(channel);
  }

  @Override
  public void deliver(final AlertNotification notification) {
    List<String> recipients = null == notification.targets() ? List.of()
        : Arrays.stream(notification.targets().split("[,;\\s]+")).map(String::trim)
            .filter(value -> value.contains("@")).toList();
    if (recipients.isEmpty()) {
      throw new IllegalArgumentException("The rule " + notification.ruleName() + " has no email");
    }
    Map<String, Object> variables = variables(notification, title);
    for (String recipient : recipients) {
      enqueue.enqueue(EnqueueNotificationCommand.builder()
          .templateCode(notification.firing() ? FIRING_TEMPLATE : RESOLVED_TEMPLATE)
          .channel(ChannelOptions.MAIL).recipient(recipient).variables(variables)
          .urgent(notification.firing()).build());
    }
  }

  /** The variables documented in docs/observabilidad/01-alertas.md (section 4). */
  static Map<String, Object> variables(final AlertNotification notification, final String title) {
    Map<String, Object> alert = new LinkedHashMap<>();
    alert.put("status", notification.status());
    alert.put("summary", notification.summary());
    alert.put("link", notification.link());
    String now = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm 'UTC'")
        .format(OffsetDateTime.now(ZoneOffset.UTC));
    alert.put(notification.firing() ? "fired_at" : "resolved_at", now);
    Map<String, Object> rule = new LinkedHashMap<>();
    rule.put("name", notification.ruleName());
    rule.put("trigger", notification.trigger());
    Map<String, Object> variables = new LinkedHashMap<>();
    variables.put("app", Map.of("title", title));
    variables.put("alert", alert);
    variables.put("rule", rule);
    variables.put("origin", Map.of("code", "", "name", ""));
    variables.put("issue",
        Map.of("title", "", "culprit", "", "count", "", "users", "", "release", ""));
    variables.put("metric", Map.of("value", "", "threshold", "", "window", ""));
    if (null != notification.details()) {
      notification.details().forEach((key, value) -> variables.merge(key, value, (base, extra) -> {
        if (base instanceof Map<?, ?> a && extra instanceof Map<?, ?> b) {
          Map<Object, Object> merged = new LinkedHashMap<>(a);
          merged.putAll(b);
          return merged;
        }
        return extra;
      }));
    }
    return variables;
  }
}
